  async function sendImages(){if(uploading||!staged.length)return;const input=document.getElementById('chatline');if(!window.socket?.connected||!own()){paintUploads('Sign in and reconnect before sending.');return;}if(!net.online){paintUploads('Image upload needs the shared bot connection.');return;}uploading=true;paintUploads('Uploading to Catbox…');try{while(staged.length){const file=staged[0],result=uploadedLinks.get(file)||await request('/upload',file,{raw:true});if(!/^https:\/\/files\.catbox\.moe\//.test(result.url))throw Error('Invalid upload response.');uploadedLinks.set(file,result);if(!window.socket?.connected)throw Error('Uploaded, but chat disconnected. Image link: '+result.url);const raw=input.value,draft=raw.trim();const combined=(draft?draft+' ':'')+result.url;if(combined.length>260)throw Error('Uploaded: '+result.url+' — shorten your draft before posting.');await postImage(combined,result.url);if(input.value===raw)input.value='';URL.revokeObjectURL(previewURLs.get(file));previewURLs.delete(file);staged.shift();}uploading=false;paintUploads();}catch(e){uploading=false;paintUploads(e.message);}}
